from scipy.optimize import least_squares
def model_lin(p,w,b):
    C=np.cos(w*t+b*t*t); S=np.sin(w*t+b*t*t)
    A=np.column_stack([C,S,np.ones_like(t),x,v,x**3,v*np.abs(v),v**3,x*v])
    return A
def fit(kind):
    best=None
    for w0 in np.linspace(0.3,0.8,11):
        for b0 in ([0.0] if kind=='const' else [-0.05,0,0.05]):
            def resid(p):
                w,b=p
                A=model_lin(None,w,b if kind=='chirp' else 0.0)
                c=np.linalg.lstsq(A,dv_dt,rcond=None)[0]
                return A@c-dv_dt
            try:
                s=least_squares(resid,[w0,b0])
            except Exception as e:
                continue
            if best is None or s.cost<best.cost: best=s
    return best
for kind in ['const','chirp']:
    s=fit(kind)
    print(kind, s.x, 2*s.cost/np.sum((dv_dt-dv_dt.mean())**2))
